import sys

def main():
    lines = [line.strip() for line in sys.stdin]
    i = 0
    while i < len(lines):
        name = lines[i]
        i += 1
        if i >= len(lines):
            break
        status = lines[i]
        i += 1
        if i >= len(lines):
            break
        title = lines[i]
        i += 1

        if title == "quit":
            print("Quitting the program.")
            break

        if status == "faculty":
            if "DVD" in title:
                print(f'DVD "{title}" successfully borrowed by {name}.')
            else:
                print("Faculty members can only borrow DVDs.")
        elif status == "student":
            if "DVD" in title:
                print(f'DVD "{title}" successfully borrowed by {name}.')
            else:
                print(f'Book "{title}" successfully borrowed by {name}.')

if __name__ == "__main__":
    main()
